import sys

def find_periods(n, s):
    def is_period(p):
        for i in range(n):
            if s[i] != '?' and s[i] != s[(i + p) % n]:
                return False
        return True

    periods = []
    for p in range(1, n + 1):
        if n % p == 0 and is_period(p):
            periods.append(p)

    return periods

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    num_cases = int(data[index])
    index += 1

    results = []

    for _ in range(num_cases):
        n = int(data[index])
        index += 1
        s = data[index]
        index += 1

        periods = find_periods(n, s)
        results.append((len(periods), periods))

    for length, periods in results:
        print(length)
        print(' '.join(map(str, periods)))

if __name__ == "__main__":
    main()
